 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    blocks = [(r, c) for r in range(h - 1) for c in range(w - 1)
              if grid[r][c] == grid[r][c + 1] == grid[r + 1][c] == grid[r + 1][c + 1] == 2]
    cols = sorted({c for _, c in blocks})
    # Alternate by distinct columns, always coloring the rightmost column group.
    selected = {c for i, c in enumerate(cols) if (len(cols) - 1 - i) % 2 == 0}
    out = [row[:] for row in grid]
    for r, c in blocks:
        if c in selected:
            for i in (r, r + 1):
                for j in (c, c + 1):
                    out[i][j] = 8
    return out
